import React, { useEffect, useState } from 'react'
import { supabase } from '../lib/supabase'
import { formatCLP } from '../lib/calculos'

export default function Caja() {
  const [movimientos, setMovimientos] = useState([])
  const [saldo, setSaldo] = useState(0)
  const [form, setForm] = useState({ fecha: new Date().toISOString().split('T')[0], tipo: 'entrada', monto: '', descripcion: '' })
  const [toast, setToast] = useState('')
  const [loading, setLoading] = useState(false)

  useEffect(() => { loadData() }, [])

  async function loadData() {
    const { data } = await supabase.from('caja').select('*').order('fecha', { ascending: false }).limit(30)
    setMovimientos(data || [])
    const s = (data || []).reduce((acc, m) => m.tipo === 'entrada' ? acc + m.monto : acc - m.monto, 0)
    setSaldo(s)
  }

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(''), 2500) }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!form.monto || !form.descripcion) return
    setLoading(true)
    const { error } = await supabase.from('caja').insert({
      fecha: form.fecha,
      tipo: form.tipo,
      monto: parseFloat(form.monto),
      descripcion: form.descripcion
    })
    if (!error) {
      showToast('Movimiento registrado')
      setForm(f => ({ ...f, monto: '', descripcion: '' }))
      loadData()
    }
    setLoading(false)
  }

  return (
    <div className="page">
      {toast && <div className="toast">{toast}</div>}
      <div className="page-title">Caja</div>

      <div className="card" style={{ textAlign: 'center', marginBottom: 20 }}>
        <div className="kpi-label">Saldo disponible</div>
        <div className="kpi-value" style={{ fontSize: 32, color: saldo >= 0 ? '#00ff88' : 'var(--pink)' }}>
          {formatCLP(saldo)}
        </div>
      </div>

      <form onSubmit={handleSubmit}>
        <div className="card">
          <div className="toggle-row">
            <button type="button"
              className={`toggle-btn ${form.tipo === 'entrada' ? 'active-entrada' : ''}`}
              onClick={() => setForm(f => ({ ...f, tipo: 'entrada' }))}>
              + Entrada
            </button>
            <button type="button"
              className={`toggle-btn ${form.tipo === 'salida' ? 'active-salida' : ''}`}
              onClick={() => setForm(f => ({ ...f, tipo: 'salida' }))}>
              - Salida
            </button>
          </div>

          <div className="form-group">
            <label className="form-label">Fecha</label>
            <input type="date" className="form-input" value={form.fecha}
              onChange={e => setForm(f => ({ ...f, fecha: e.target.value }))} />
          </div>

          <div className="form-group">
            <label className="form-label">Monto ($)</label>
            <input type="number" className="form-input" value={form.monto}
              placeholder="ej: 9000"
              onChange={e => setForm(f => ({ ...f, monto: e.target.value }))} />
          </div>

          <div className="form-group">
            <label className="form-label">Descripción</label>
            <input type="text" className="form-input" value={form.descripcion}
              placeholder="ej: Venta Mojito frambuesa, Compra limones..."
              onChange={e => setForm(f => ({ ...f, descripcion: e.target.value }))} />
          </div>

          <button type="submit" className="btn btn-primary" disabled={loading}>
            {loading ? 'Guardando...' : 'Registrar movimiento'}
          </button>
        </div>
      </form>

      <div className="section-divider">Últimos movimientos</div>
      <div className="card">
        {movimientos.length === 0 && (
          <div style={{ color: 'var(--muted)', textAlign: 'center', padding: 20 }}>Sin movimientos</div>
        )}
        {movimientos.map(m => (
          <div className="list-item" key={m.id}>
            <div>
              <div className="list-item-name">{m.descripcion}</div>
              <div className="list-item-sub">{m.fecha}</div>
            </div>
            <div className="list-item-right">
              <div className="list-item-value" style={{ color: m.tipo === 'entrada' ? '#00ff88' : 'var(--pink)' }}>
                {m.tipo === 'entrada' ? '+' : '-'}{formatCLP(m.monto)}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}
